# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_composer_binary() {
    local dir
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    [[ -d "$dir/vendor/bin" ]] || return 0
    local file
    for file in "$dir/vendor/bin"/*; do
        [[ -f "$file" ]] && printf '%s\n' "${file##*/}"
    done
}

_choice_composer_config_key() {
    _helper_composer_config_list | gawk -F'[][]' '/^\[/ { print $2 }'
}

_choice_composer_global_command() {
    composer list --raw 2>/dev/null | gawk '{ print $1 }'
}

_choice_composer_package() {
    local dir lock
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    lock="$dir/composer.lock"
    if [[ -f "$lock" ]]; then
        jq -b -r '[(.packages // [])[], (."packages-dev" // [])[]] | .[] | .name // empty' "$lock" 2>/dev/null
    else
        jq -b -r '((.require // {}) + (."require-dev" // {})) | keys[]' "$dir/composer.json" 2>/dev/null \
            | grep -Ev '^(php|hhvm|ext-|lib-)'
    fi
}

_choice_composer_platform() {
    local dir
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    (cd "$dir" && composer show --platform --format=json 2>/dev/null) \
        | jq -b -r '(.platform // [])[] | "\(.name)\t\(.version // "")"'
}

_choice_composer_policy() {
    printf '%s\n' advisories malware abandoned
    _helper_composer_config_list \
        | gawk -F'[][]' '/^\[policy\./ { key = $2; sub(/^policy\./, "", key); sub(/\..*$/, "", key); print key }'
}

_choice_composer_repository() {
    _helper_composer_config_list \
        | gawk -F'[][]' '/^\[repositories\./ { key = $2; sub(/^repositories\./, "", key); sub(/\.[^.]+$/, "", key); print key }'
}

_choice_composer_script() {
    local dir
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    jq -b -r '(.scripts // {}) | keys[]' "$dir/composer.json" 2>/dev/null
}

_choice_composer_type() {
    local dir lock
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    lock="$dir/composer.lock"
    [[ -f "$lock" ]] || return 0
    jq -b -r '[(.packages // [])[], (."packages-dev" // [])[]] | .[] | .type // empty' "$lock" 2>/dev/null
}

_helper_composer_config_list() {
    if [[ -n "${argc_global:-}" ]]; then
        composer config --global --list 2>/dev/null
        return 0
    fi
    local dir
    dir="$(_helper_composer_project_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    (cd "$dir" && composer config --list 2>/dev/null)
}

_helper_composer_project_dir() {
    if [[ -n "${argc_working_dir:-}" ]]; then
        printf '%s\n' "$argc_working_dir"
    else
        _argc_util_path_search_parent -p composer.json
    fi
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
